_FALLBACK_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Running cost: 3.0 per truck and 1.5 per scooter not on its own base;\n# couriers on their own base cost nothing and serve nothing.\n#\n# Conservative fallback: begin with a shortest-path return-home plan, then\n# accept only immediate harvests that improve its revenue after both running\n# costs and a reserve covering the entire unpaid journey home. No speculative\n# travel, opponent prediction, persistent targets, or marginal fights.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 60\nUNIT_TYPES = {\n    "truck": (8, 3.0, 1),\n    "scooter": (3, 1.5, 2),\n}\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        row = [n + 1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if row[neighbor] == n + 1:\n                    row[neighbor] = row[node] + 1\n                    queue.append(neighbor)\n        distances.append(row)\n\n    reachable = {}\n    for speed in (1, 2):\n        reachable[speed] = [\n            [destination for destination in range(n)\n             if distances[source][destination] <= speed]\n            for source in range(n)\n        ]\n    return distances, reachable\n\n\ndef payout(own_capacity, opponent_capacity, stock):\n    denominator = max(own_capacity + opponent_capacity, stock)\n    if denominator <= 0:\n        return 0.0\n    return own_capacity * stock / denominator\n\n\ndef return_reserve(node, base, speed, cost, distances):\n    # The final move arrives home and is free. All earlier return turns cost.\n    steps = (distances[node][base] + speed - 1) // speed\n    return cost * max(0, steps - 1)\n\n\ndef return_destination(source, base, speed, distances, reachable):\n    return min(\n        reachable[speed][source],\n        key=lambda node: (distances[node][base], node),\n    )\n\n\ndef make_plan(obs, distances, reachable, deadline):\n    n = int(obs["n_nodes"])\n    base = int(obs["player_base"])\n    units = obs.get("player_units", {})\n    stocks = obs.get("stock", [0.0] * n)\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n\n    opponent_capacity = [0] * n\n    for kind, node in obs.get("opponent_units", {}).values():\n        if kind in UNIT_TYPES and 0 <= node < n:\n            opponent_capacity[node] += UNIT_TYPES[kind][0]\n\n    # A complete, legal, conservative plan exists before any improvement.\n    plan = {}\n    capacity = [0] * n\n    valid_ids = []\n    for uid in sorted(units):\n        kind, source = units[uid]\n        if kind not in UNIT_TYPES or not 0 <= source < n:\n            continue\n        cap, cost, speed = UNIT_TYPES[kind]\n        destination = return_destination(\n            source, base, speed, distances, reachable\n        )\n        plan[uid] = destination\n        capacity[destination] += cap\n        valid_ids.append(uid)\n\n    # Larger, efficient harvesters choose first; scooters fill smaller leftovers.\n    valid_ids.sort(key=lambda uid: (units[uid][0] != "truck", uid))\n\n    for uid in valid_ids:\n        if time.perf_counter() >= deadline:\n            break\n\n        kind, source = units[uid]\n        cap, cost, speed = UNIT_TYPES[kind]\n        default = plan[uid]\n        capacity[default] -= cap\n\n        def value(destination):\n            before = payout(\n                capacity[destination],\n                opponent_capacity[destination],\n                stocks[destination],\n            )\n            after = payout(\n                capacity[destination] + cap,\n                opponent_capacity[destination],\n                stocks[destination],\n            )\n            expense = cost if destination != base else 0.0\n            # On the final turn there are no future running costs to reserve.\n            reserve = (\n                return_reserve(destination, base, speed, cost, distances)\n                if remaining > 1 else 0.0\n            )\n            return after - before - expense - reserve\n\n        best = default\n        best_value = value(default)\n        for destination in reachable[speed][source]:\n            if destination == default:\n                continue\n            # Do not initiate contests. Mandatory return moves remain allowed.\n            if destination != base and opponent_capacity[destination] > 0:\n                continue\n            candidate_value = value(destination)\n            # Require a clear improvement rather than chasing tiny differences.\n            if candidate_value > best_value + 0.30:\n                best = destination\n                best_value = candidate_value\n\n        plan[uid] = best\n        capacity[best] += cap\n\n    return plan\n\n\ndef legal_action(plan, units, n, distances):\n    moves = {}\n    for uid in sorted(plan):\n        if uid not in units:\n            continue\n        kind, source = units[uid]\n        if kind not in UNIT_TYPES or not 0 <= source < n:\n            continue\n        destination = int(plan[uid])\n        if not 0 <= destination < n:\n            continue\n        if distances[source][destination] > UNIT_TYPES[kind][2]:\n            continue\n        if destination != source:\n            moves[str(uid)] = int(destination)\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self._map_key = None\n        self._distances = None\n        self._reachable = None\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0, 0.6 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return {"moves": {}}\n\n        edges = obs.get("edges", [])\n        key = (n, tuple((int(a), int(b)) for a, b in edges))\n        if key != self._map_key:\n            distances, reachable = preprocess_map(n, edges)\n            self._distances = distances\n            self._reachable = reachable\n            self._map_key = key\n\n        plan = make_plan(\n            obs, self._distances, self._reachable, deadline\n        )\n        return legal_action(\n            plan, obs.get("player_units", {}), n, self._distances\n        )\n'
